contract InvMutTest {
    C c;
    bool didRevert;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, string calldata description) external {
        // Grant admin to caller so the call should succeed
        c.setAdmin(caller, true);
        // Now caller is admin, call should succeed
        didRevert = !address(this).call(abi.encodeWithSelector(C.newEmergencyOracle.selector, description));
        // The general property: if caller is admin, the call must succeed (not revert)
        assert(c.isAdmin(caller) == !didRevert);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, string calldata desc) public payable {
        require(true);
        bool reverted; try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? c.isAdmin(caller) : true);
    }
}

