    function testFuzz_property(address admin, string calldata description) public {
        vm.assume(admin != address(0));
        vm.prank(admin);
        try c.newEmergencyOracle(description) {
        } catch {
            assertTrue(false, "newEmergencyOracle should succeed");
        }
        address oracle = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), admin, bytes1(uint8(1)))))));
